44	function mergeContactTheatreStateSources(
45	  fileState: Record<string, unknown> | null,
46	  savedState: Record<string, unknown> | null,
47	): Record<string, unknown> | null {
48	  if (!fileState) return savedState;
49	  if (!savedState) return fileState;
50	  const fileSheetsById = readContactRecord(fileState.sheetsById) ?? {};
51	  const savedSheetsById = readContactRecord(savedState.sheetsById) ?? {};
52	  return {
53	    ...fileState,
54	    ...savedState,
55	    sheetsById: {
56	      ...fileSheetsById,
57	      ...savedSheetsById,
58	    },
59	  };
60	}
61	
62	function readContactTheatreFileState(): Record<string, unknown> | null {
63	  const rawState = contactState as Record<string, unknown>;
64	  return sanitizeContactTheatreState(rawState);
65	}
66	
67	function readSavedContactTheatreState(): Record<string, unknown> | null {
68	  return TheatreStateStorageService.read({
69	    ...CONTACT_THEATRE_STORAGE_OPTIONS,
70	    sanitize: sanitizeContactTheatreState,
71	    validate: (state) => state != null,
72	  });
73	}
74	
75	function resolveContactTheatreStateSource(): Record<string, unknown> | null {
76	  const fileState = readContactTheatreFileState();
77	  TheatreStateStorageService.seedFromFileState(
78	    fileState,
79	    CONTACT_THEATRE_STORAGE_OPTIONS,
80	  );
81	  if (!resolveContactAuthorMode()) {
82	    return fileState ?? (contactState as Record<string, unknown>);
83	  }
84	  return mergeContactTheatreStateSources(
85	    fileState,
86	    readSavedContactTheatreState(),
87	  );
88	}
