90	class ContactTheatreRuntime {
91	  private static _instance: ContactTheatreRuntime | null = null;
92	
93	  private readonly _rig = new ContactSceneRig();
94	  private readonly _stateSource = resolveContactTheatreStateSource();
95	  private readonly _project = TheatreProjectSession.open<
96	    ContactTheatreValue,
97	    ContactTheatreProps
98	  >(CONTACT_THEATRE_PROJECT_ID, {
99	    state: this._stateSource ?? undefined,
100	  });
101	  private readonly _objectBySheetId = new Map<
102	    ContactTheatreSheetId,
103	    ContactTheatreObject
104	  >();
105	  private readonly _sequenceBySheetId = new Map<
106	    ContactTheatreSheetId,
107	    ContactTheatreSequence
108	  >();
109	  private readonly _lengthBySheetId = new Map<ContactTheatreSheetId, number>();
110	
111	  private constructor() {
112	    CONTACT_THEATRE_SHEET_IDS.forEach((sheetId) => {
113	      const sheet = TheatreSheetSession.open(this._project, sheetId);
114	      const object = sheet.object(
115	        CONTACT_THEATRE_OBJECT_ID,
116	        this._rig.createDefaultValue(),
117	        { reconfigure: true },
118	      );
119	      const sequence = TheatreSequenceSession.get(sheet);
120	      this._objectBySheetId.set(sheetId, object);
121	      this._sequenceBySheetId.set(sheetId, sequence);
122	      this._lengthBySheetId.set(
123	        sheetId,
124	        this._resolveSheetLength(sheetId, sequence),
125	      );
126	    });
127	  }
128	
129	  static getInstance(): ContactTheatreRuntime {
130	    if (ContactTheatreRuntime._instance) {
131	      return ContactTheatreRuntime._instance;
132	    }
133	    ContactTheatreRuntime._instance = new ContactTheatreRuntime();
134	    return ContactTheatreRuntime._instance;
135	  }
136	
137	  readState(
138	    sheetId: ContactTheatreSheetId,
139	    position = 0,
140	  ): ContactTheatreValue {
141	    const binding = this._resolveSheetBinding(sheetId);
142	    if (!binding) {
143	      return this._rig.createDefaultValue();
144	    }
145	    const previousPosition = binding.sequence.position;
146	    try {
147	      binding.sequence.position = this._clampPosition(position, binding.length);
148	      return this._rig.readObjectValue(binding.object.value);
149	    } finally {
150	      binding.sequence.position = previousPosition;
151	    }
152	  }
153	
154	  applyBootState(engine: Engine): void {
155	    this._syncSheetState(engine, CONTACT_INTRO_AUTOPLAY_SHEET_ID, 0);
156	  }
157	
158	  async startIntroAutoplay(engine: Engine): Promise<void> {
159	    await this._startSheetAutoplayForDuration(
160	      engine,
161	      CONTACT_INTRO_AUTOPLAY_SHEET_ID,
162	      CONTACT_INTRO_AUTOPLAY_DURATION_MS,
163	    );
164	  }
165	
166	  async startOuttroAutoplay(engine: Engine): Promise<void> {
167	    await this._startSheetAutoplayForDuration(
168	      engine,
169	      CONTACT_OUTTRO_AUTOPLAY_SHEET_ID,
170	      CONTACT_OUTTRO_AUTOPLAY_DURATION_MS,
171	    );
172	  }
173	
174	  private async _startSheetAutoplayForDuration(
175	    engine: Engine,
176	    sheetId: ContactTheatreSheetId,
177	    durationMs: number,
178	  ): Promise<void> {
179	    const binding = this._resolveSheetBinding(sheetId);
180	    if (!binding) {
181	      this._syncSheetToEnd(engine, sheetId);
182	      return;
183	    }
184	    const playbackRange = this._resolvePlaybackRange(sheetId, binding.length);
185	    if (playbackRange.end <= playbackRange.start) {
186	      Logger.warn(CLASS, "_startSheetAutoplayForDuration", "Invalid duration playback range.", {
187	        sheetId,
188	        playbackRange,
189	        durationMs,
190	      });
191	      this._syncSheetToEnd(engine, sheetId);
192	      return;
193	    }
194	    const rate = this._resolvePlaybackRateForDuration(playbackRange, durationMs);
195	    await this._playSheetAutoplay(
196	      engine,
197	      sheetId,
198	      binding,
199	      playbackRange,
200	      durationMs,
201	    );
202	  }
203	
204	  private async _playSheetAutoplay(
205	    engine: Engine,
206	    sheetId: ContactTheatreSheetId,
207	    binding: ContactTheatreSheetBinding,
208	    playbackRange: ContactTheatrePlaybackRange,
209	    durationMs: number,
210	  ): Promise<void> {
211	    binding.sequence.pause();
212	    binding.sequence.position = playbackRange.start;
213	    const disposePlayback = TheatrePlaybackService.bindValues(
214	      binding.object,
215	      (values) => {
216	        this._rig.apply(engine, values);
217	      },
218	    );
219	    this._rig.apply(engine, binding.object.value);
220	    try {
221	      const gsap = this._getGsap();
222	      if (gsap) {
223	        await this._playSheetAutoplayWithGsap(
224	          engine,
225	          binding,
226	          playbackRange,
227	          durationMs,
228	          gsap,
229	        );
230	      } else {
231	        const rate = this._resolvePlaybackRateForDuration(
232	          playbackRange,
233	          durationMs,
234	        );
235	        await this._playSheetAutoplayWithSequence(binding, playbackRange, rate);
236	      }
237	    } finally {
238	      binding.sequence.pause();
239	      disposePlayback();
240	    }
241	    this._syncSheetState(engine, sheetId, playbackRange.end);
242	  }
243	
244	  private _playSheetAutoplayWithSequence(
245	    binding: ContactTheatreSheetBinding,
246	    playbackRange: ContactTheatrePlaybackRange,
247	    rate: number,
248	  ): Promise<void> {
249	    return binding.sequence
250	      .play({
251	      range: [playbackRange.start, playbackRange.end],
252	      rate,
253	      })
254	      .then(() => undefined);
255	  }
256	
257	  private _playSheetAutoplayWithGsap(
258	    engine: Engine,
259	    binding: ContactTheatreSheetBinding,
260	    playbackRange: ContactTheatrePlaybackRange,
261	    durationMs: number,
262	    gsap: GsapGlobal,
263	  ): Promise<void> {
264	    return new Promise<void>((resolve) => {
265	      const state = { position: playbackRange.start };
266	      gsap.killTweensOf?.(state);
267	      gsap.to(state, {
268	        position: playbackRange.end,
269	        duration: durationMs / 1000,
270	        ease: CONTACT_THEATRE_AUTOPLAY_EASE,
271	        onUpdate: () => {
272	          binding.sequence.position = state.position;
273	          this._rig.apply(engine, binding.object.value);
274	        },
275	        onComplete: () => {
276	          binding.sequence.position = playbackRange.end;
277	          this._rig.apply(engine, binding.object.value);
278	          resolve();
279	        },
280	      });
281	    });
282	  }
283	
284	  private _getGsap(): GsapGlobal | null {
285	    return ((window as WindowWithGsap).gsap ?? null) as GsapGlobal | null;
286	  }
287	
288	  private _syncSheetToEnd(engine: Engine, sheetId: ContactTheatreSheetId): void {
289	    const binding = this._resolveSheetBinding(sheetId);
290	    const length = binding?.length ?? 0;
291	    const playbackRange = this._resolvePlaybackRange(sheetId, length);
292	    this._syncSheetState(engine, sheetId, playbackRange.end);
293	  }
294	
295	  private _syncSheetState(
296	    engine: Engine,
297	    sheetId: ContactTheatreSheetId,
298	    position: number,
299	  ): void {
300	    this._rig.apply(engine, this.readState(sheetId, position));
301	  }
302	
303	  private _resolveSheetBinding(
304	    sheetId: ContactTheatreSheetId,
305	  ): ContactTheatreSheetBinding | null {
306	    const object = this._objectBySheetId.get(sheetId) ?? null;
307	    const sequence = this._sequenceBySheetId.get(sheetId) ?? null;
308	    const length = this._lengthBySheetId.get(sheetId) ?? 0;
309	    if (!object || !sequence) {
310	      return null;
311	    }
312	    return {
313	      object,
314	      sequence,
315	      length,
316	    };
317	  }
318	
319	  private _resolvePlaybackRange(
320	    sheetId: ContactTheatreSheetId,
321	    length: number,
322	  ): ContactTheatrePlaybackRange {
323	    const configuredRange = CONTACT_THEATRE_PLAYBACK_RANGES[sheetId] ?? null;
324	    if (configuredRange) {
325	      return {
326	        start: this._clampPosition(configuredRange.start, length),
327	        end: this._clampPosition(configuredRange.end, length),
328	      };
329	    }
330	    const keyedRange = this._resolveTrackPlaybackRange(sheetId, length);
331	    if (keyedRange) {
332	      return keyedRange;
333	    }
334	    return {
335	      start: 0,
336	      end: Number.isFinite(length) && length > 0 ? length : 0,
337	    };
338	  }
339	
340	  private _resolveTrackPlaybackRange(
341	    sheetId: ContactTheatreSheetId,
342	    sheetLength: number,
343	  ): ContactTheatrePlaybackRange | null {
344	    const tracksByObject = this._readSheetTracksByObject(sheetId);
345	    const objectTracks = tracksByObject?.[CONTACT_THEATRE_OBJECT_ID];
346	    if (!objectTracks || typeof objectTracks !== "object") return null;
347	    const trackData = (objectTracks as Record<string, unknown>).trackData;
348	    if (!trackData || typeof trackData !== "object") return null;
349	
350	    let minPosition = Number.POSITIVE_INFINITY;
351	    let maxPosition = Number.NEGATIVE_INFINITY;
352	
353	    Object.values(trackData as Record<string, unknown>).forEach((trackState) => {
354	      if (!trackState || typeof trackState !== "object") return;
355	      const keyframes = (trackState as Record<string, unknown>).keyframes;
356	      if (!Array.isArray(keyframes)) return;
357	      const positions = keyframes
358	        .map((keyframe) => {
359	          if (!keyframe || typeof keyframe !== "object") return null;
360	          const position = (keyframe as Record<string, unknown>).position;
361	          return typeof position === "number" ? position : null;
362	        })
363	        .filter(
364	          (position): position is number =>
365	            typeof position === "number" && Number.isFinite(position),
366	        );
367	      if (positions.length < 2) return;
368	      minPosition = Math.min(minPosition, ...positions);
369	      maxPosition = Math.max(maxPosition, ...positions);
370	    });
371	
372	    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition)) {
373	      return null;
374	    }
375	    if (maxPosition <= minPosition) return null;
376	
377	    return {
378	      start: this._clampPosition(minPosition, sheetLength),
379	      end: this._clampPosition(maxPosition, sheetLength),
380	    };
381	  }
382	
383	  private _readSheetTracksByObject(
384	    sheetId: ContactTheatreSheetId,
385	  ): Record<string, unknown> | null {
386	    const sheetsById = readContactRecord(this._stateSource?.sheetsById);
387	    if (!sheetsById) return null;
388	    const sheetState = readContactRecord(sheetsById[sheetId]);
389	    if (!sheetState) return null;
390	    const sequence = readContactRecord(sheetState.sequence);
391	    if (!sequence) return null;
392	    return readContactRecord(sequence.tracksByObject);
393	  }
394	
395	  private _resolveSheetLength(
396	    sheetId: ContactTheatreSheetId,
397	    sequence: ContactTheatreSequence,
398	  ): number {
399	    const directLength =
400	      typeof sequence.length === "number" ? sequence.length : null;
401	    if (
402	      directLength != null &&
403	      Number.isFinite(directLength) &&
404	      directLength > 0
405	    ) {
406	      return directLength;
407	    }
408	    const stateLength = this._readSheetLengthFromState(sheetId);
409	    if (stateLength > 0) {
410	      return stateLength;
411	    }
412	    return 0;
413	  }
414	
415	  private _resolvePlaybackRateForDuration(
416	    playbackRange: ContactTheatrePlaybackRange,
417	    durationMs: number,
418	  ): number {
419	    const durationSeconds = durationMs / 1000;
420	    const span = playbackRange.end - playbackRange.start;
421	    if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) {
422	      return 1;
423	    }
424	    if (!Number.isFinite(span) || span <= 0) {
425	      return 1;
426	    }
427	    return span / durationSeconds;
428	  }
429	
430	  private _readSheetLengthFromState(sheetId: ContactTheatreSheetId): number {
431	    const sheetsById = readContactRecord(this._stateSource?.sheetsById);
432	    if (!sheetsById) return 0;
433	    const sheetState = readContactRecord(sheetsById[sheetId]);
434	    if (!sheetState) return 0;
435	    const sequence = readContactRecord(sheetState.sequence);
436	    if (!sequence) return 0;
437	    const length = sequence.length;
438	    if (typeof length !== "number") return 0;
439	    if (!Number.isFinite(length) || length <= 0) return 0;
440	    return length;
441	  }
442	
443	  private _clampPosition(value: number, max: number): number {
444	    if (!Number.isFinite(value)) return 0;
445	    return Math.max(0, Math.min(max, value));
446	  }
447	}
