84	export class ContactTheatreBridge {
85	  private _authorSheetId: ContactTheatreSheetId = PRIMARY_SHEET_ID;
86	  private _sampling = false;
87	  private _disposed = false;
88	  private _lastSampleAt = 0;
89	  private _recordScrub: ContactTheatreScrub | null = null;
90	  private readonly _sheetById = new Map<
91	    ContactTheatreSheetId,
92	    TheatreSheetPort<ContactTheatreValue, ContactTheatreProps>
93	  >();
94	  private readonly _objectBySheetId = new Map<
95	    ContactTheatreSheetId,
96	    ContactTheatreObject
97	  >();
98	  private readonly _sequenceBySheetId = new Map<
99	    ContactTheatreSheetId,
100	    ContactTheatreSequence
101	  >();
102	  private readonly _rig = new ContactSceneRig();
103	  private readonly _hooks: ContactTheatreBridgeHooks;
104	  private readonly _engine: Engine;
105	  private readonly _controls: OrbitControls;
106	  private readonly _onControlsStart: () => void;
107	  private readonly _onControlsEnd: () => void;
108	  private readonly _onControlsChange: () => void;
109	  private readonly _onExportClick: () => void;
110	  private readonly _onSheetChange: (event: Event) => void;
111	  private readonly _onMatchPrevClick: () => void;
112	  private _unsubscribeValues: (() => void) | null = null;
113	  private _unsubscribeSelection: (() => void) | null = null;
114	  private _syncingStudioSelection = false;
115	
116	  private constructor(
117	    engine: Engine,
118	    controls: OrbitControls,
119	    hooks: ContactTheatreBridgeHooks,
120	  ) {
121	    this._engine = engine;
122	    this._controls = controls;
123	    this._hooks = hooks;
124	    this._onControlsStart = () => this._recordStart();
125	    this._onControlsEnd = () => this._recordEnd();
126	    this._onControlsChange = () => this._recordFrame();
127	    this._onExportClick = () => void this._exportSaveFile();
128	    this._onSheetChange = (event) => {
129	      const select = event.currentTarget;
130	      if (!(select instanceof HTMLSelectElement)) return;
131	      this._setAuthorSheetId(select.value);
132	    };
133	    this._onMatchPrevClick = () => this._matchFromPrevious();
134	  }
135	
136	  static async create(
137	    engine: Engine,
138	    controls: OrbitControls,
139	    hooks: ContactTheatreBridgeHooks,
140	  ): Promise<ContactTheatreBridge | null> {
141	    if (window.location.pathname.indexOf(CONTACT_PAGE_TYPE) === -1) return null;
142	    if (!resolveContactAuthorMode()) return null;
143	    try {
144	      const bridge = new ContactTheatreBridge(engine, controls, hooks);
145	      await bridge._init();
146	      return bridge;
147	    } catch (_error) {
148	      return null;
149	    }
150	  }
151	
152	  dispose(): void {
153	    if (this._disposed) return;
154	    this._disposed = true;
155	    this._controls.removeEventListener("start", this._onControlsStart);
156	    this._controls.removeEventListener("end", this._onControlsEnd);
157	    this._controls.removeEventListener("change", this._onControlsChange);
158	    this._recordScrub?.discard();
