1413	  private _resolveRevealTransitionMs(target: HTMLElement): number {
1414	    const computedStyle = window.getComputedStyle(target);
1415	    const durations = this._parseCssTimeList(computedStyle.transitionDuration);
1416	    const delays = this._parseCssTimeList(computedStyle.transitionDelay);
1417	    const entries = Math.max(durations.length, delays.length, 1);
1418	    let maxMs = 0;
1419	
1420	    for (let index = 0; index < entries; index += 1) {
1421	      const duration = durations[index] ?? durations[durations.length - 1] ?? 0;
1422	      const delay = delays[index] ?? delays[delays.length - 1] ?? 0;
1423	      maxMs = Math.max(maxMs, duration + delay);
1424	    }
1425	
1426	    return Math.max(maxMs, CONTACT_WIZARD.transitionMs) + CONTACT_WIZARD.transitionBufferMs;
1427	  }
